"""Experiment result reporting utilities."""

import sys


def report_result(name, value):
    """Print a single experiment result in KEY: VALUE format."""
    print(f"{name}: {value}")
    sys.stdout.flush()


def run_experiments(experiments):
    """Run a list of (name, callable) experiment pairs."""
    for name, func in experiments:
        try:
            value = func()
            report_result(name, value)
        except Exception as e:
            report_result(name, f"ERROR: {e}")
"""Transition system representation for verification."""


class TransitionSystem:
    """A symbolic transition system defined by state variables,
    initial condition, transition relation, and safety property."""

    def __init__(self, name, state_vars, init, trans, safety):
        self.name = name
        self.state_vars = state_vars
        self.init = init
        self.trans = trans
        self.safety = safety

    def __repr__(self):
        return f"TransitionSystem({self.name}, vars={len(self.state_vars)})"
