# -- bounded concretization ---------------------------------------------------

def _bmc_search(self, max_depth=25):
    """Bounded model checking: unroll the transition relation up to
    max_depth looking for a concrete safety violation.

    Returns a concrete Counterexample for the shallowest violating
    depth, or None if no violation is reachable within the bound.
    """
    self._uid += 1
    uid = self._uid
    chain = [[Int(f"__bmc{uid}_{i}_{j}") for j in range(len(self.curr))]
             for i in range(max_depth + 1)]

    def at(expr, i):
        return substitute(expr, *zip(self.curr, chain[i]))

    def trans_at(i):
        return substitute(self.trans_rel, *(list(zip(self.curr, chain[i]))
                                            + list(zip(self.primed, chain[i + 1]))))

    s = Solver()
    s.set("timeout", QUERY_TIMEOUT_MS)
    s.add(at(self.init_cond, 0))
    for k in range(max_depth + 1):
        if k > 0:
            s.add(trans_at(k - 1))
        s.push()
        s.add(at(Not(self.safety), k))
        if s.check() == sat:
            m = s.model()
            states = [State({str(c): _to_int(m.eval(sc, model_completion=True))
                             for c, sc in zip(self.curr, chain[i])})
                      for i in range(k + 1)]
            return Counterexample([Transition(states[i], states[i + 1],
                                              f"step_{i}")
                                   for i in range(k)], states=states)
        s.pop()
    return None

